# 마지막 적재 후 0:40:00 → 알림 (기준 30분)
last_week = {"가구": 0.30, "의류": 0.40, "전자": 0.30}
today     = {"가구": 0.10, "의류": 0.45, "전자": 0.45}
psi = sum((today[k]-last_week[k]) * math.log(today[k]/last_week[k]) for k in last_week)
print(f"PSI {psi:.3f}")  # PSI 0.286

with ThreadPoolExecutor(max_workers=8) as pool:
    futures = {pool.submit(handle, o): o for o in range(100, 108)}
    for f, o in futures.items():
        try: ok.append(f.result())
        except Exception: retry.append(o)   # retry 토픽으로
print(sorted(ok))        # [100, 101, 102, 104, 105, 106, 107]
print(retry)             # [103]
print(max(ok) + 1)       # 108 ← 커밋할 offset
